template.script:
(function () {
    function paoFolioPerPage() {
        var vars = {};
        var params = document.location.search.substring(1).split('&');
        for (var i = 0; i != params.length; i++) {
            var pair = params[i].split('=', 2);
            vars[pair[0]] = decodeURIComponent(pair[1] || '');
        }
        var page = parseInt(vars['page'] || '1', 10) || 1;
        var nodes = document.getElementsByClassName('o_pao_folio');
        for (var j = 0; j != nodes.length; j++) {
            var base = nodes[j].getAttribute('data-folio') || '';
            var match = base.match(/^(.*?)(\d+)$/);
            if (!match) {
                continue;
            }
            var number = String(parseInt(match[2], 10) + page - 1);
            while (match[2].length > number.length) {
                number = '0' + number;
            }
            nodes[j].textContent = match[1] + number;
        }
    }
    if (document.readyState == 'loading') {
        document.addEventListener('DOMContentLoaded', paoFolioPerPage);
    } else {
        paoFolioPerPage();
    }
})();
